class SocialRuntimeCheck {
 static int assertions;static void Check(bool value,string name){if(!value)throw new Exception(name);assertions++;}static bool Near(float a,float b){return Math.Abs(a-b)<.0001f;}
 static Oracle NewOracle(string extra=""){var game=new RainWorldGame();var room=new Room{game=game,design=new IteratorDesign{oracleId=Guid.NewGuid().ToString(),dialogueJson="{\"testNonce\":\""+Guid.NewGuid().ToString()+"\",\"enabled\":true,\"first\":[],\"pearlReading\":{\"greetingEnabled\":false,\"manyEnabled\":false}"+extra+"}"}};var oracle=new Oracle{room=room};room.updateList.Add(oracle);return oracle;}
 static Player NewPlayer(Oracle o){var player=new Player{room=o.room};o.room.game.Players.Add(new AbstractCreature{realizedCreature=player});return player;}
 static CreatorDialogueLine Line(string text){return new CreatorDialogueLine{text=text,gap=0,hold=.1f};}
 static PearlVariant Group(string text){return new PearlVariant{lines=new[]{Line(text)}};}
 static void Drain(CreatorPearlReader reader,Oracle o,Player player,int ticks=150){for(int i=0;i<ticks;i++){o.room.game.clock++;o.room.game.cameras[0].hud.dialogBox.ShowingAMessage=false;reader.Update(player,o.room.design,true);}}
 static void Offer(Oracle o,Player player,DataPearl pearl,bool toward=true,bool release=true){
  if(Vector2.Distance(player.mainBodyChunk.pos,o.firstChunk.pos)<16)o.firstChunk.pos=player.mainBodyChunk.pos+new Vector2(200,0);
  pearl.room=o.room;pearl.firstChunk.pos=player.mainBodyChunk.pos;var grasp=new Grasp{grabber=player,grabbed=pearl};pearl.grabbedBy.Add(grasp);var old=player.grasps;var next=new Grasp[old.Length+1];Array.Copy(old,next,old.Length);next[old.Length]=grasp;player.grasps=next;
  On.Player.Invoke(delegate(Player p,int index,bool eu){if(!release)return;pearl.grabbedBy.Clear();p.grasps[index]=null;pearl.firstChunk.vel=(o.firstChunk.pos-p.mainBodyChunk.pos).normalized*(toward?10:-10);},player,old.Length,false);
 }
 static List<string> Said(Oracle o){return o.room.game.cameras[0].hud.dialogBox.said;}
 static void QueueAndActions(){
  var queue=new CreatorDialogueState();int a=0,b=0;var line=Line("last main");queue.Begin(new[]{line},delegate {a++;});queue.Next();queue.Interrupt(new[]{Line("response")},delegate {b++;});queue.Next();queue.Finish();queue.Finish();Check(a==0&&b==1,"response completion is consumed once");Check(queue.Next()==line,"main final line replays after interruption");queue.Finish();queue.Finish();Check(a==1,"replayed final line fires once after completion");
  queue.Begin(new[]{Line("cancelled")},delegate {a++;});queue.Next();queue.Clear();queue.Finish();Check(a==1,"replay/reset discards cancelled occurrence action");queue.Begin(new CreatorDialogueLine[0],delegate {a++;});queue.Next();queue.Finish();Check(a==1,"empty group cannot act");queue.Interrupt(new[]{Line("old response")},delegate {a++;});queue.Next();queue.Interrupt(new[]{Line("replacement")});queue.Next();queue.Finish();Check(a==1,"replaced response cannot act later");
  var o=NewOracle();var player=NewPlayer(o);var actions=CreatorDialogueActions.For(o);var done=actions.Completed(new CreatorGroupAction{type="killPlayer",delay=1},player);done();for(int i=0;i<40;i++)actions.Update();Check(player.deaths==0&&Near(((IteratorBehavior)o.oracleBehavior).killFac,0),"delay precedes finite native charge");CreatorRuntime.Paused=true;for(int i=0;i<80;i++)actions.Update();Check(player.deaths==0&&actions.Active,"pause freezes action");CreatorRuntime.Paused=false;for(int i=0;i<39;i++)actions.Update();Check(player.deaths==0&&((IteratorBehavior)o.oracleBehavior).killFac>0,"native charge remains finite and visible");actions.Update();for(int i=0;i<80;i++)actions.Update();Check(player.deaths==1&&o.room.sparks==20&&!actions.Active,"one completion emits one native kill with 20 sparks");
  player.dead=false;done=actions.Completed(new CreatorGroupAction{type="killPlayer",delay=1},player);done();player.room=new Room();actions.Update();player.room=o.room;for(int i=0;i<100;i++)actions.Update();Check(player.deaths==1&&!actions.Active,"leaving cancels delayed kill permanently");done=actions.Completed(new CreatorGroupAction{type="killPlayer"},player);done();CreatorEncounter.Restart++;actions.Update();Check(!actions.Active,"restart aborts pending action");done();Check(!actions.Active,"stale group callback cannot act after replay");
  done=actions.Completed(new CreatorGroupAction{type="killPlayer"},player);done();CreatorRuntime.Mode="silent";actions.Update();Check(!actions.Active&&((IteratorBehavior)o.oracleBehavior).lastKillFac==0,"silent mode clears both native visual factors");CreatorRuntime.Mode="story";done=actions.Completed(new CreatorGroupAction{type="killPlayer"},player);done();StudioRuntime.Recording=true;actions.Update();Check(!actions.Active,"recording is nonlethal");StudioRuntime.Recording=false;
 }
 static void Affinity(){
  var rules=new CreatorAffinityRules();var state=new CreatorAffinityState(.3f,4);Check(state.Tier=="neutral","native initial tier");Check(CreatorAffinityState.TierOf(-.5f)=="dislikes"&&CreatorAffinityState.TierOf(0)=="neutral"&&CreatorAffinityState.TierOf(.5f)=="likes","tier boundaries inclusive on upper tier");rules.attackMode="gradual";Check(state.Hit(rules,false)=="neutral"&&Near(state.value,.1f),"rock selects pre-hit tier before penalty");Check(state.Hit(rules,true)=="neutral"&&Near(state.value,-.4f),"spear selects pre-hit tier with distinct penalty");rules.attackMode="vanilla";Check(state.Hit(rules,false)=="dislikes"&&state.value==-1&&!state.eligible,"vanilla one hit mutes and disables cycle recovery");
  state=CreatorAffinityState.Load(state.Data(),.3f,4);Check(!state.Advance(4)&&state.value==-1,"reload/current-cycle read grants no recovery");Check(state.Advance(5)&&state.value==-1&&state.eligible,"hit cycle receives no bonus then next cycle is eligible");Check(state.Advance(6)&&Near(state.value,-.85f),"later clean completed cycle recovers once");Check(!state.Advance(6)&&!state.Advance(3)&&Near(state.value,-.85f),"duplicate save and cycle rollback cannot improve affinity");
  var o=NewOracle();CreatorAffinity.Update(o,o.room.design);var records=o.room.game.GetStorySession.saveState.miscWorldSaveData.unrecognizedSaveStrings;Check(records.Count==1,"initial untouched state persists baseline cycle");var saved=new List<string>(records);var restored=NewOracle();restored.room.design.oracleId=o.room.design.oracleId;restored.room.game.GetStorySession.saveState.miscWorldSaveData.unrecognizedSaveStrings=saved;restored.room.game.GetStorySession.saveState.cycleNumber=1;CreatorAffinity.Update(restored,restored.room.design);Check(Near(CreatorAffinity.Get(restored,restored.room.design).value,.45f),"new game reload restores own campaign state before recovery");var other=NewOracle();Check(Near(CreatorAffinity.Get(other,other.room.design).value,.3f),"different oracle/campaign remains isolated");
 }
 static void PearlFlow(){
  var o=NewOracle();var player=NewPlayer(o);var p=CreatorDialogueProfile.For(o.room.design);p.pearlReading.preRead=new[]{Group("prelude")};p.pearlReading.misc=new[]{Group("misc body")};var pearl=new DataPearl{room=o.room};o.room.physicalObjects[0].Add(pearl);var reader=new CreatorPearlReader(o);Offer(o,player,pearl);Drain(reader,o,player);Check(Said(o).Count==2&&Said(o)[0]=="prelude"&&Said(o)[1]=="misc body","ordinary pearl prelude occurs once before selected body");Drain(reader,o,player);Check(Said(o).Count==2,"completed loose pearl does not repeat every frame");
  o=NewOracle();player=NewPlayer(o);p=CreatorDialogueProfile.For(o.room.design);p.affinity.initial=-.8f;p.affinity.refusal=new[]{Group("refused")};p.pearlReading.misc=new[]{Group("must not read")};pearl=new DataPearl{room=o.room};o.room.physicalObjects[0].Add(pearl);reader=new CreatorPearlReader(o);Offer(o,player,pearl);Drain(reader,o,player);Check(Said(o).Count==1&&Said(o)[0]=="refused"&&Near(pearl.firstChunk.vel.x,10)&&pearl.firstChunk.vel.y==0,"low affinity refuses once before taking or reading");var records=o.room.game.GetStorySession.saveState.miscWorldSaveData.unrecognizedSaveStrings;Check(records.Count==2,"refusal persists affinity/story only without foreign native state");
  o=NewOracle();player=NewPlayer(o);p=CreatorDialogueProfile.For(o.room.design);p.pearlReading.misc=new[]{Group("misc allowed")};var colored=new DataPearl{room=o.room};colored.AbstractPearl.dataPearlType=DataPearl.AbstractDataPearl.DataPearlType.Colored;o.room.physicalObjects[0].Add(colored);o.room.physicalObjects[0].Add(new CreatorWorkPearl{room=o.room});reader=new CreatorPearlReader(o);Drain(reader,o,player);Check(Said(o).Count==0,"colored and working pearls are never swallowed by miscellaneous pool");
  pearl=new DataPearl{room=o.room};pearl.AbstractPearl.dataPearlType=DataPearl.AbstractDataPearl.DataPearlType.Misc2;o.room.physicalObjects[0].Add(pearl);Offer(o,player,pearl);Drain(reader,o,player);Check(Said(o).Count==1&&Said(o)[0]=="misc allowed","Misc2 shares ordinary pool");
  o=NewOracle();player=NewPlayer(o);pearl=new DataPearl{room=o.room};o.room.physicalObjects[0].Add(pearl);reader=new CreatorPearlReader(o);Offer(o,player,pearl);Drain(reader,o,player);Check(Said(o).Contains("native body")&&Conversation.lastFile==38&&Conversation.lastSeed==pearl.abstractPhysicalObject.ID.RandomSeed,"empty authored misc pool uses safe seeded native text loader");
  Conversation.fail=true;o=NewOracle();player=NewPlayer(o);pearl=new DataPearl{room=o.room};o.room.physicalObjects[0].Add(pearl);reader=new CreatorPearlReader(o);Offer(o,player,pearl);Drain(reader,o,player);Check(Said(o).Count==0&&MiDiagnostics.codes.Contains("MI-MISC-PEARL-TEXT"),"native text failure is diagnosed without fabricated/read-complete body");Conversation.fail=false;
 }
 static void GreetingsAndObservation(){
  var o=NewOracle();var player=NewPlayer(o);var p=CreatorDialogueProfile.For(o.room.design);p.pearlReading.greetingEnabled=true;p.pearlReading.greetingDelay=0;p.pearlReading.greeting=new[]{Group("A")};p.pearlReading.greetingItems=new[]{Group("item B")};p.pearlReading.greetingWeapons=new[]{Group("weapon B")};player.grasps=new[]{new Grasp{grabbed=new PhysicalObject{room=o.room}},new Grasp{grabbed=new Rock{room=o.room}}};var reader=new CreatorPearlReader(o);Drain(reader,o,player);Check(Said(o).Count==2&&Said(o)[0]=="A"&&Said(o)[1]=="weapon B","entry A plus exclusive weapon B use separate selected groups");
  o=NewOracle();player=NewPlayer(o);p=CreatorDialogueProfile.For(o.room.design);p.observation.weapons=new[]{Group("observed weapon")};p.pearlReading.misc=new[]{new PearlVariant{lines=new[]{Line("body one"),Line("body two")}}};var pearl=new DataPearl{room=o.room};o.room.physicalObjects[0].Add(pearl);reader=new CreatorPearlReader(o);Offer(o,player,pearl);reader.Update(player,o.room.design,true);Check(Said(o).Contains("body one"),"read started");player.grasps=new[]{new Grasp{grabbed=new Spear{room=o.room}}};Drain(reader,o,player);Check(Said(o).Count==2&&Said(o)[1]=="body two","new held weapon cannot interrupt active reading or queue a stale response");player.grasps=new[]{new Grasp{grabbed=new Rock{room=o.room}}};Drain(reader,o,player);Check(Said(o).Count==3&&Said(o)[2]=="observed weapon","newly presented weapon near idle iterator is observed once");Drain(reader,o,player);Check(Said(o).Count==3,"still-held observation is not repeated");
 }
