 static void ExitBoundaries(){
  RejectedExit("negative exit",-1,delegate(Room r){},false);RejectedExit("out of range exit",99,delegate(Room r){},false);
  var invalid=new Action<Room>[] {
   delegate(Room r){r.abstractRoom.connections[1]=-1;},delegate(Room r){r.abstractRoom.connections=null;},delegate(Room r){r.abstractRoom.nodes=null;},delegate(Room r){r.abstractRoom.nodes[1].type=AbstractRoomNode.Type.Den;},
   delegate(Room r){r.shortCutsReady=false;},delegate(Room r){r.world.rooms.Remove(8);},delegate(Room r){r.world.rooms[8].connections=new[]{-1};},
   delegate(Room r){r.shortcutOverride=new ShortcutData{StartTile=new RWCustom.IntVector2(40,50),destNode=1,shortCutType=ShortcutData.Type.Normal};},
   delegate(Room r){r.shortcutOverride=new ShortcutData{StartTile=new RWCustom.IntVector2(40,50),destNode=0,shortCutType=ShortcutData.Type.RoomExit};},
   delegate(Room r){r.shortcutEntrance=false;},delegate(Room r){r.shortcutThrows=true;}
  };
  var names=new[]{"disconnected exit","missing connections","missing nodes","non-exit node","shortcuts not ready","missing destination","missing return connection","non-room shortcut","mismatched shortcut node","non-entrance terrain","shortcut lookup exception"};
  for(int i=0;i<invalid.Length;i++){RejectedExit(names[i],1,invalid[i],false);RejectedExit(names[i],1,invalid[i],true);}
  var o=NewOracle();var player=NewPlayer(o);player.shortcutThrows=true;var actions=CreatorDialogueActions.For(o);int reports=MiDiagnostics.codes.Count;var callback=actions.Completed(ExitAction(),player);callback();actions.Completed(ExitAction(),player)();TickAction(actions,100);callback();TickAction(actions,100);
  Check(player.shortcutCalls==1&&!actions.Active&&MiDiagnostics.codes.Count==reports+1&&MiDiagnostics.codes[reports]=="MI-DIALOGUE-ACTION","private native shortcut exception is reported once with no queued or repeated retry");
 }
 static void ExitInterruptedRequests(){
