   try{TickAction(actions,100);callback();TickAction(actions,100);Check(player.shortcutCalls==0&&!actions.Active,"interrupted exit clears all queued requests permanently: "+reason);}finally{CreatorRuntime.Mode="story";StudioRuntime.Recording=false;}
  }
